window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d9d9d7aacdde9535"]={"versions": [{"id": "FIG-d9d9d7aacdde9535", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm ist ein PDU- bzw. Frame-Layout-Diagramm (Bit-/Byte-Struktur) aus der Spezifikation des FlexRay Transport Protocol (<code>FrTp</code>) im Kontext der AUTOSAR Classic Platform Communication Stack Architecture. Es definiert den bitgenauen Aufbau des ersten segmentierten Übertragungsrahmens (<em>First Frame</em>, FF) im ISO-konformen Adressier-/Formatierungsmodus (ISO 10681-2).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das dargestellte N-PDU-Format gliedert sich in zwei Hauptbereiche:</p>\n<ul class=\"fig-list\"><li><strong>PCI (Protocol Control Information)</strong>: Gesamtlänge 2 Byte (16 Bit), farblich orange codiert, unterteilt in:\n<ul class=\"fig-list\"><li><code>FT</code> (Frame Type): 4 Bit zur Kennzeichnung des Rahmentyps First Frame.\n</li><li><code>DL</code> (Data Length): 12 Bit zur Angabe der Gesamtlänge der zu übertragenden Gesamtbotschaft.\n</li></ul>\n</li><li><strong>Data</strong>: Nutzdatenfeld, farblich gelb codiert, mit der Beschriftung „Length depending on configuration“ (N-SDU-Nutzdatenanteil im ersten Frame).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Bei segmentierter Datenübertragung leitet der Sender den Transfer mit dem First Frame ein. Der Empfänger entnimmt den ersten beiden Bytes die Protokollsteuerinformation (<code>PCI</code>): Das Feld <code>FT</code> identifiziert die PDU als First Frame, während <code>DL</code> die Gesamtlänge der vollständigen Botschaft (bis zu 4095 Bytes über 12 Bit) signalisiert. Der verbleibende Platz des FlexRay-Frames transportiert die ersten Nutzdaten (<code>Data</code>), woraufhin die Flusssteuerung (<em>Flow Control</em>) bzw. nachfolgende Consecutive Frames (<code>CF</code>) initiiert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Layout ist normativ für die FrTp-Segmentierung nach ISO-Standard. Entwickler müssen die Bit-Ausrichtung bei der Serialisierung/Deserialisierung beachten: Die 16 Bit der PCI teilen sich in das 4-Bit-Feld <code>FT</code> (obere Bits / MSBs von Byte 0) und das 12-Bit-Feld <code>DL</code> (untere 4 Bits von Byte 0 sowie Byte 1). Die tatsächliche Nutzdatenlänge im First Frame ergibt sich dynamisch aus der konfigurierten PDU-Größe abzüglich der 2 Byte PCI.</p>"}, {"id": "FIG-a21c4ab1a6e114f7", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm ist ein PDU- bzw. Frame-Layout-Diagramm (Bit-/Byte-Struktur) aus der Spezifikation des FlexRay Transport Protocol (<code>FrTp</code>) im Kontext der AUTOSAR Classic Platform Communication Stack Architecture. Es definiert den bitgenauen Aufbau des ersten segmentierten Übertragungsrahmens (<em>First Frame</em>, FF) im ISO-konformen Adressier-/Formatierungsmodus (ISO 10681-2).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das dargestellte N-PDU-Format gliedert sich in zwei Hauptbereiche:</p>\n<ul class=\"fig-list\"><li><strong>PCI (Protocol Control Information)</strong>: Gesamtlänge 2 Byte (16 Bit), farblich orange codiert, unterteilt in:\n<ul class=\"fig-list\"><li><code>FT</code> (Frame Type): 4 Bit zur Kennzeichnung des Rahmentyps First Frame.\n</li><li><code>DL</code> (Data Length): 12 Bit zur Angabe der Gesamtlänge der zu übertragenden Gesamtbotschaft.\n</li></ul>\n</li><li><strong>Data</strong>: Nutzdatenfeld, farblich gelb codiert, mit der Beschriftung „Length depending on configuration“ (N-SDU-Nutzdatenanteil im ersten Frame).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Bei segmentierter Datenübertragung leitet der Sender den Transfer mit dem First Frame ein. Der Empfänger entnimmt den ersten beiden Bytes die Protokollsteuerinformation (<code>PCI</code>): Das Feld <code>FT</code> identifiziert die PDU als First Frame, während <code>DL</code> die Gesamtlänge der vollständigen Botschaft (bis zu 4095 Bytes über 12 Bit) signalisiert. Der verbleibende Platz des FlexRay-Frames transportiert die ersten Nutzdaten (<code>Data</code>), woraufhin die Flusssteuerung (<em>Flow Control</em>) bzw. nachfolgende Consecutive Frames (<code>CF</code>) initiiert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Layout ist normativ für die FrTp-Segmentierung nach ISO-Standard. Entwickler müssen die Bit-Ausrichtung bei der Serialisierung/Deserialisierung beachten: Die 16 Bit der PCI teilen sich in das 4-Bit-Feld <code>FT</code> (obere Bits / MSBs von Byte 0) und das 12-Bit-Feld <code>DL</code> (untere 4 Bits von Byte 0 sowie Byte 1). Die tatsächliche Nutzdatenlänge im First Frame ergibt sich dynamisch aus der konfigurierten PDU-Größe abzüglich der 2 Byte PCI.</p>"}], "trans": [{"from": "FIG-d9d9d7aacdde9535", "to": "FIG-a21c4ab1a6e114f7", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
